-- HOLIDAYS · Halloween · Halloween · 10–12 · continuing
do $mig$
declare
  v_course uuid; v_unit uuid; v_lesson uuid;
  v_media text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'holidays';
  if v_course is null then raise exception 'course holidays not found'; end if;

  select id into v_unit from classroom_units
   where course_id = v_course and title = 'Halloween' limit 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Halloween', 1) returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and title = 'Halloween · 10–12 · continuing' limit 1;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, summary, sort_order, is_published, pass_threshold, kind)
    values (v_unit, 'Halloween · 10–12 · continuing', 'Урок-игра для 10–12 лет, продолжающие', 4, false, 60, 'lesson')
    returning id into v_lesson;
  else
    update classroom_lessons set summary = 'Урок-игра для 10–12 лет, продолжающие', sort_order = 4,
           is_published = false, pass_threshold = 60, kind = 'lesson'
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    -- блок 1 (sort_order 0) · интерактивный урок
    (v_lesson, 'embed', replace($blk${"url": "https://classroom.wowteach.ru/lessons/halloween/10-12_continuing.html"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    -- блок 2 (sort_order 1) · как провести — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<div style=\"padding:16px 18px;background:#fff7ec;border-radius:14px;border:2px solid #f3d3a3\">\n<h3 style=\"margin:0 0 6px;color:#8a3c08\">🎃 Как провести урок</h3>\n<p style=\"margin:0 0 8px\">«Планы уроков» → этот урок → <b>«▶ Показ»</b>: урок откроется на весь экран. Демонстрируйте в Zoom <b>эту вкладку</b>, а не весь экран.</p>\n<p style=\"margin:0 0 8px\">План урока — кнопка 📋 вверху справа внутри урока (откроется отдельным окном) или ниже на этой странице.</p>\n<p style=\"margin:0\">Если удобнее отдельной вкладкой: <a href=\"https://classroom.wowteach.ru/lessons/halloween/10-12_continuing.html\">открыть урок</a>. Нужен интернет: картинки и музыка загружаются с сервера.</p></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    -- блок 3 (sort_order 2) · план — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>План урока</h3><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Длительность:</b> 40 мин. &nbsp; <b>Мотивация:</b> детектив — ученик ищет улики, получает эликсир правды, допрашивает подозреваемых и находит вора Золотой тыквы. Вор каждый раз случайный.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>📖 История (расскажите в начале, по-русски или простыми фразами):</b> В маленьком городке Spooky Town на главной площади стояла <b>Золотая тыква</b> — главное украшение праздника Хэллоуин. Вечером 30 октября, ровно в 9:15, она пропала! Утром 31-го об этом написали все газеты. Полиция не справляется, поэтому зовут лучшего детектива — <b>ученика</b>. Помогает ему кошка-сыщик <b>Inspector Whiskers</b>. Подозреваемых шестеро: ведьма Wanda, вампир Count Vlad, мумия Mumford, оборотень Wolfie, скелет Mr Bones и привидение Boo. За урок детектив соберёт пять улик, найдёт <b>эликсир правды</b> (кто его выпьет, не может соврать), проверит сумки, допросит подозреваемых и найдёт вора. <b>Вор каждый раз выбирается случайно</b> — даже учитель не знает его заранее.</div><div style=\"background:#fff3cd;border:3px solid #c0392b;border-radius:12px;padding:12px 16px;margin:10px 0;font-weight:700;color:#7a1f12\">⚠️ ЕСЛИ НЕ ХВАТАЕТ ВРЕМЕНИ — НАЖМИТЕ ЗНАЧОК 🗄 (EVIDENCE ROOM, ВВЕРХУ СПРАВА, РЯДОМ С 📋). ОН ЕСТЬ НА ВСЕХ СТРАНИЦАХ ДО ДОПРОСА. УЧЕНИК НАЖИМАЕТ НА УЛИКИ, КОТОРЫХ У НЕГО ЕЩЁ НЕТ, — И ВЫ СРАЗУ ПЕРЕХОДИТЕ К ДОПРОСУ. СТРЕЛКА ← ВЕРНЁТ НА СТРАНИЦУ, С КОТОРОЙ ВЫ ПРИШЛИ.</div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Стр.</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Задание и инструкция</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Teacher's language</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Suggested answers / Students' answers</th></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">1</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Начало: площадь и Золотая тыква → газета (3 шага, Next).</b> На экране площадь Spooky Town, на постаменте — Золотая тыква (она мигает). Учитель спрашивает, что это и зачем она на площади. Next / нажатие на тыкву — ок. Next — тыква исчезает (тот же кадр, пустой постамент). Next — вылетает газета «THIEF STEALS THE GOLDEN PUMPKIN!». Расскажите историю (см. выше).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What can you see?\" \"What happened to the pumpkin?\" \"What does the newspaper say?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a golden pumpkin.\" \"It disappeared! Someone stole it.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">2</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Подозреваемые.</b> Шесть карточек: портрет и имя. Ученик выбирает, о ком узнать, — нажатие открывает информацию. Next открывает следующую. <b>Вор каждый раз выбирается случайно</b> — заранее его не знает никто.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Tell me about Count Vlad.\" \"What does he look like?\" \"Who do you think is the thief?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"He is tall. He has got a black cape. He sleeps all day.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">3</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Фонарик (3 раунда).</b> Тёмная площадь, предметы спрятаны. Учитель водит фонарик мышкой (без мыши он бродит сам), ученик говорит, куда светить. Нашли — нажмите на предмет. Последний предмет — часы. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Find the lantern! Left or right? Up or down?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Go left… stop! It's a watch. It stopped at 9:15!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">4</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Свидетель (3 вопроса).</b> Сова Mrs Owl рассказывает, что видела. Учитель читает рассказ (он на экране), ученик отвечает на вопросы и выбирает ответ. Нажмите на верный вариант. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Read the owl's story. What time was it? What was the person wearing? Where did they go?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It was quarter past nine.\" \"A long black coat.\" \"They went to the park.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">5</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Шифровка.</b> Записка из символов, внизу — алфавит-ключ. Ученик находит символ в ключе и называет букву, учитель нажимает на символ в записке — появляется буква. Послание: SEE YOU AT THE CAFE. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What letter is this?\" \"Find the symbol in the key.\" \"What does the note say?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"S-E-E… See you at the cafe! The thief went to the cafe.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">6</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Следы.</b> Карта городка. <b>Подсказок на карте нет</b>: ученик читает указание справа и говорит направление; следы появляются только после верной стрелки. Учитель нажимает стрелку — кошка идёт. 5 шагов, в конце — старая башня. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Read the next step. Where do we go?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Go left to the park.\" \"Turn right and go to the cafe.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">7</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>До и после (6 отличий).</b> Площадь до кражи и после. Ученик называет отличия, учитель нажимает на них (на любой картинке). В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Compare the pictures. What happened?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"In the first picture there is a pumpkin. In the second picture there isn't.\" \"The bench fell over.\" \"The jar is empty — someone ate the lollipops!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">8</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>What happened last night? (5 карточек).</b> Ученик восстанавливает путь вора по порядку — как шли по следам. Нажимаете на карточку, которую называет ученик: верная встаёт в ленту, неверная трясётся («Try again!»). Над ячейками — First, Then, After that, Next, Finally: ученик рассказывает историю целиком.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What happened first? And then?\" \"Tell me the whole story.\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"First, at 9:15 the thief took the Golden Pumpkin. Then the thief ran to the park. After that… Finally, the thief climbed the old tower.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">9</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Spot the lie (3 раунда).</b> Трое подозреваемых рассказывают, что видели ночью. Один врёт — его слова не сходятся с уликами. Ученик находит лжеца и объясняет, почему; нажмите на него — штамп LIE! и ответ внизу. Это <b>не</b> про алиби и на поиск вора не влияет. Вывод: «They're lying! We need a truth elixir!»</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who is lying? Why?\" \"How do you know?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Count Vlad is lying. The pumpkin was stolen at 9:15, so he couldn't see it at 10 o'clock.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">10</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Правда или ложь (6 утверждений).</b> Проверяем, что запомнили. Ученик отвечает, учитель нажимает TRUE / FALSE: верная кнопка «вдавливается» с ✓, при ошибке — «Try again!». Награда — <b>эликсир правды</b>. <i>Объясните по-русски: кошка нашла волшебный эликсир — кто его выпьет, не сможет соврать. На допросе подозреваемые выпьют его и будут отвечать честно.</i></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Is it true or false?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"False. The thief went to the park, not to the cinema.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">11</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Рентген сумок (все 6 подозреваемых).</b> У каждого своя сумка. Нажмите на сумку — сверху вниз проходит лазер, внутри видны тени предметов. Ученик угадывает предмет, учитель нажимает на тень — предмет проявляется. У двух случайных подозреваемых (но никогда не у вора) в сумке <b>билет в кино на 9:00</b> — это алиби, они получают штамп NOT GUILTY.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What can you see in the bag? Where was he at 9:15?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a cinema ticket. He was at the cinema, so he is not guilty.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">12</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Prepare your questions.</b> Для каждой улики ученик сам пишет вопрос полностью и нажимает ✓ (или Enter). Регистр и знаки не важны. Неверно — поле трясётся. 💡 — подсказка: слова вопроса вперемешку. Next — подставляет правильный вопрос.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Write a question for each clue.\" \"Check the word order.\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Where were you at 9:15?\" \"Did you go to the park?\" \"Did you go to the cafe?\" \"Did you climb the tower?\" \"Did you eat the lollipops?\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">13</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Допрос. Решает ученик.</b> Подозреваемые пьют эликсир правды. <b>Сначала нажмите на улику</b> (слева) — появится вопрос. Ученик задаёт его, учитель <b>нажимает на подозреваемого</b> — тот отвечает. Справа — решение по выбранному подозреваемому: <b>NOT GUILTY</b> или <b>THE THIEF!</b> Нажимаете, когда ученик сам скажет и объяснит. Если решение неверное, программа не даст его принять. Передумал — нажмите на подозреваемого со штампом и <b>↩ Undo</b> (снимаются и штампы с рентгена).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Choose a clue. Ask everybody. Who is not guilty? Why?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Where were you at 9:15?\" — \"I was at home.\" \"Did you go to the cafe?\" — \"No, I didn't.\" \"He is not guilty because he didn't go to the cafe.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">14</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Финал.</b> Вор в наручниках у полицейского участка, кошка с Золотой тыквой, «CASE CLOSED!». Сразу выскакивает окно <b>«What's your name, detective?»</b> — ученик вписывает имя, ✓ — имя появляется на значке. ✏️ Name — исправить, 💾 Save — скачать картинку. Справа кнопки <b>🏁 Finish</b> (сразу на финальный слайд) и <b>⭐ Extra</b> (дополнительные задания: bucket list, потом настольная игра).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who stole the pumpkin? How do you know?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's Count Vlad because he went to the cafe and he climbed the tower.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">15</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Бонус (если есть время): Halloween bucket list.</b> Нажатие на карточку — в список, нажатие в списке — убрать. Внизу можно дописать свой пункт. Внизу справа кнопки 🏁 Finish (на финальный слайд) и ⭐ Extra (настольная игра).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What would you like to do this Halloween? Why?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I'd like to go to a party because I love costumes.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">16</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Extra: настольная игра «Spooky Town».</b> Сюда ведёт кнопка ⭐ Extra на странице bucket list. Выберите фишки (1–5 игроков, можно вписать имена) → ▶ Play. Кубик — по очереди (Next тоже бросает). На клетках «?» — вопрос о Хэллоуине (How do people celebrate Halloween in your country?, What scares you the most?, Tell a short scary story in three sentences.). Ученик отвечает развёрнуто. ⏩ +2, ⏪ −2, ⭐ — весёлое задание (Make a scary face! / Say BOO! / Fly like a bat!). Кто первым дошёл до башни 🏁 — победил. 🏁 Finish внизу справа — закончить урок в любой момент.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Roll the dice!\" \"Answer the question. Tell us more!\" \"Why?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I'd like to be a vampire because…\" \"I don't believe in ghosts because…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">17</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Finish.</b> «Great job, detective! Happy Halloween!» — конфетти, прощаемся.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Great job! Happy Halloween! Bye!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Happy Halloween!\"</td></tr></table><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗂️ Лексика и грамматика:</b> Past Simple: Did you…? Yes, I did / No, I didn't • was / were, was wearing • Where were you at…? • time: quarter past nine • go past, turn left / right • because</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0;font-size:13px;color:#777\"><b>Навигация:</b> ← → — назад / пропустить; Next загорается, когда задание выполнено, а в играх с раундами ведёт к следующему раунду (подсказывает ответ). Кружочки страниц вверху слева кликабельны. 🗄 — склад улик, 📋 — этот план, 🎵 — музыка.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🏠 Домашнее задание</b> — материал <b>«Halloween Homework · 10–12 · continuing»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. Задания:<ol style=\"margin:6px 0 0 22px\"><li>Карточки (12 слов)</li><li>Соедини слово и картинку</li><li>Собери слово из букв</li><li>Послушай и напиши</li><li>Лишнее слово</li><li>Текст «The Golden Pumpkin» с пропусками</li><li>🎤 Опиши подозреваемого</li></ol><div style=\"color:#777;font-size:13px;margin-top:4px\">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    -- блок 4 (sort_order 3) · ДЗ — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Halloween Homework · 10–12 · continuing»</b> в этом же юните. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 3)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  delete from classroom_blocks where lesson_id = v_lesson and sort_order >= 4;
  update classroom_blocks set audience = 'shared' where lesson_id = v_lesson and sort_order = 0;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 1;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 2;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 3;
end
$mig$;
